function syncFeedback(p){if(['castlefight','treetag','warlock','kodotag'].includes(session.snapshot?.options?.mode))return;const countInventory=u=>{const counts={};for(const slot of u.inventory||[])if(slot)counts[slot.key]=(counts[slot.key]||0)+slot.charges;return counts;};const next={owner:p.owner,time:session.snapshot.time,gold:p.gold,level:p.level,essence:p.essence||0,attributes:{...p.attributes},tomes:{...p.tomeAttributes},skills:{...p.skillLevels},inventory:countInventory(p),equipment:p.inventory.map(s=>s?{key:s.key,level:s.level||1,enchantment:s.enchantment,permanent:s.permanentEnchant?.id}:null)};const old=feedbackCheckpoint;feedbackCheckpoint=next;if(!old||old.owner!==next.owner||next.time<old.time)return;
 if(next.gold>old.gold)feedback.play({kind:'gold',amount:next.gold-old.gold,title:'Ouro recebido'});
 if(next.essence>old.essence)feedback.play({kind:'essence',title:'+'+(next.essence-old.essence)+' essência(s)',detail:'Revele três técnicas alternativas na tela Espólios.'});
 if(next.level>old.level)feedback.play({kind:'level',title:'Nível '+next.level,detail:'+'+(next.level-old.level)+' ponto(s) de habilidade · distribua seus novos atributos',icon:icon('avatar')});
 for(const [key,rank]of Object.entries(next.skills))if(rank>(old.skills[key]||0))feedback.play({kind:old.skills[key]?'upgrade':'learn',key,title:SKILLS[key].name,detail:(old.skills[key]?'Nível '+old.skills[key]+' → '+rank:'Técnica aprendida · nível '+rank)+' · '+p.skillPoints+' ponto(s) restante(s)',icon:icon(key)});
 for(const [key,count]of Object.entries(next.inventory))if(count>(old.inventory[key]||0))feedback.play({kind:'item',key,title:ITEMS[key].name,detail:'Na mochila · '+(p.inventory.find(s=>s?.key===key&&s.xpValue)?.xpValue?'Tomo de '+p.inventory.find(s=>s?.key===key&&s.xpValue).xpValue+' XP':ITEMS[key].description),icon:icon(key)});
 for(const [index,slot]of next.equipment.entries())if(slot&&old.equipment[index]?.key===slot.key&&slot.level>old.equipment[index].level)feedback.play({kind:'equipment',key:slot.key,title:ITEMS[slot.key].name,detail:'Nível '+old.equipment[index].level+' → '+slot.level+' · bônus atualizados',icon:icon(slot.key)});
 for(const [index,slot]of next.equipment.entries())if(slot?.enchantment&&old.equipment[index]?.key===slot.key&&slot.enchantment!==old.equipment[index].enchantment)feedback.play({kind:'enchant',key:slot.key,title:ENCHANTMENTS[slot.enchantment].name,detail:ITEMS[slot.key].name+' · '+(ENCHANTMENTS[slot.enchantment].element?'resistência elemental aplicada':'efeito aplicado aos ataques diretos'),icon:icon(slot.enchantment==='fire'?'fireball':slot.enchantment==='frost'?'frostnova':'poison')});
 for(const [index,slot]of next.equipment.entries())if(slot?.permanent&&slot.permanent!==old.equipment[index]?.permanent){const rune=permanentEnchantAt(p.inventory[index].permanentEnchant,slot.key);feedback.play({kind:'enchant',title:rune.name,detail:LOOT_RARITIES[rune.rarity].name+' · '+rune.description,icon:icon('gungnir')});}
 for(const [key,value]of Object.entries(next.tomes))if(value>(old.tomes?.[key]||0))feedback.play({kind:'attribute',title:ATTRIBUTES[key].name+' +'+(value-(old.tomes?.[key]||0)),detail:'Tomo consumido · bônus permanente nesta partida'});
 for(const [key,value]of Object.entries(next.attributes))if(value>old.attributes[key])feedback.play({kind:'attribute',title:ATTRIBUTES[key].name+' +'+(value-old.attributes[key]),detail:'Valor base: '+value+' · '+p.attributePoints+' ponto(s) restante(s)'});
}
