function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');toastUntil=performance.now()+2800;}
function me(){return session.snapshot?.units.find(u=>u.id===session.snapshot.players[session.playerId]);}
function currentSkill(p,key){return skillFor(p,key);}
function displayOutcome(){return session.snapshot?.phase==='victory'&&!(session.snapshot.winningOwners?.length?session.snapshot.winningOwners.includes(session.playerId):session.snapshot.winner===session.playerId)?'defeat':session.snapshot?.phase;}
