function send(command){const ok=sendCommand(command),point=ok&&rtsMovementMarkerPoint(command);if(point)view.mark(point);return ok;}
function sendCommand(command){if(localLobby&&!localLobby.started){try{const ok=localLobby.command(command);session.game=localLobby.game;session.snapshot=localLobby.snapshot();if(!ok)return false;if(command.type==='roomSettings'){begin();session.dialog=[];session.paused=false;$('novel').classList.add('hidden');}if(['roomStart','roomSelectionComplete'].includes(command.type)){feedbackCheckpoint=null;session.paused=false;session.dialog=[];$('novel').classList.add('hidden');view.reset();renderShop();}return true;}catch(error){toast(error.message);return false;}}if(session.game){const ok=session.game.command(session.playerId,command);session.snapshot=session.game.snapshotFor(session.playerId);if(ok&&me())syncFeedback(me());if(!ok){const reason=session.game.commandFailureReason||'Confira alvo, alcance, recursos ou fase da partida.';toast(reason);feedback.play({kind:'error',title:'Ação não concluída',detail:reason});}return ok;}if(session.socket?.readyState===1){session.socket.send(JSON.stringify({type:'command',command}));return true;}return false;}
