 if(session.mode==='cast'){const s=SKILLS[p.skills[session.castSlot]];if(s.target==='enemy'&&(!unit||unit.team===p.team)){toast('Escolha um inimigo para essa técnica.');return;}if(send({type:'cast',slot:session.castSlot,target:unit?.id,...point}))setMode();}
