 document.querySelectorAll('[data-ro-lineage]').forEach(b=>b.onclick=()=>{roSelectedLineage=b.dataset.roLineage;session.selected=roLineage(roSelectedLineage).hero;roAccountUI.setLineage(roSelectedLineage);renderHeroChoices('bonk');});
