 await setupUI.load();disconnect();$('error').textContent='Conectando à aldeia…';$('online').disabled=true;
 try{const transport=await connectPhaseRoom({room,name:selectedName(),baseUrl:setupUI.phaseBase(),onState:state=>{if(session.socket===transport)session.snapshot=state;},onError:message=>{if(session.socket===transport)toast(message);},onClose:()=>{if(session.socket===transport)$('connection').textContent='Desconectado';}});session.socket=transport;session.game=null;session.playerId=transport.id;session.snapshot=transport.state;begin();$('connection').textContent='Phase Killer · sala '+transport.room;$('error').textContent='';}
