function openDialog(lines){if(!lines?.length)return;session.dialog=lines;session.dialogIndex=0;session.paused=!!session.game;$('novel').classList.remove('hidden');showDialog();}
function showDialog(){const [speaker,role,text]=session.dialog[session.dialogIndex];$('speaker').textContent=speaker;$('dialog-role').textContent=role;$('dialog-text').setAttribute('aria-label',text);$('reveal-dialog').disabled=false;writer.start(text);$('dialog-page').textContent=`${session.dialogIndex+1} / ${session.dialog.length}${session.game?' · treino pausado':' · online continua'}`;$('next-dialog').textContent=session.dialogIndex===session.dialog.length-1?'Vamos lá →':'Continuar →';}
